ound: rgba(52, 211, 153, 0.08);\r\n  border: 1px solid rgba(52, 211, 153, 0.2);\r\n  color: rgba(52, 211, 153, 0.9);\r\n}\r\n.zhino-api-result.fail {\r\n  background: rgba(var(--zn-danger-rgb), 0.08);\r\n  border: 1px solid rgba(var(--zn-danger-rgb), 0.2);\r\n  color: rgba(var(--zn-danger-rgb), 0.9);\r\n}\r\n\r\n.zhino-api-badge {\r\n  font-size: 10px;\r\n  padding: 1px 6px;\r\n  border-radius: 8px;\r\n  background: rgba(var(--zn-accent-rgb), 0.15);\r\n  color: rgba(var(--zn-accent-rgb), 0.85);\r\n  flex-shrink: 0;\r\n}\r\n\r\n.zhino-api-warn {\r\n  margin-top: 8px;\r\n  padding: 8px;\r\n  background: rgba(var(--zn-warn-rgb), 0.08);\r\n  border: 1px solid rgba(var(--zn-warn-rgb), 0.2);\r\n  border-radius: 4px;\r\n  font-size: 11px;\r\n  color: rgba(var(--zn-warn-rgb), 0.85);\r\n  line-height: 1.5;\r\n}\r\n\r\n/* ===== API 监听器 ===== */\r\n.zhino-api-monitor-desc {\r\n  font-size: 10px;\r\n  color: var(--zn-text-muted);\r\n  margin-top: 4px;\r\n}\r\n/* 监听日志：tabs/body 在 Modal 内，遮罩+卡片+头部+关闭 由 Modal 提供 */\r\n.zhino-monitor-tabs {\r\n  display: flex;\r\n  gap: 4px;\r\n  padding: 8px 12px;\r\n  border-bottom: 1px solid var(--zn-border-light);\r\n  flex-shrink: 0;\r\n  overflow-x: auto;\r\n}\r\n.zhino-monitor-tab {\r\n  background: var(--zn-bg-surface1);\r\n  border: 1px solid var(--zn-border-light);\r\n  border-radius: 6px;\r\n  color: var(--zn-text-regular);\r\n  cursor: pointer;\r\n  padding: 6px 12px;\r\n  font-size: 11px;\r\n  text-align: center;\r\n  white-space: nowrap;\r\n  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);\r\n}\r\n.zhino-monitor-tab:hover { color: var(--zn-text-primary); }\r\n.zhino-monitor-tab.active {\r\n  background: rgba(52, 211, 153, 0.12);\r\n  border-color: rgba(52, 211, 153, 0.3);\r\n  color: rgba(52, 211, 153, 0.9);\r\n}\r\n.zhino-monitor-tab-sub {\r\n  display: block;\r\n  font-size: 9px;\r\n  opacity: 0.6;\r\n  margin-top: 2px;\r\n}\r\n.zhino-monitor-body {\r\n  overflow-y: auto;\r\n  padding: 12px 16px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 12px;\r\n}\r\n.zhino-monitor-meta {\r\n  display: flex;\r\n  gap: 20px;\r\n  font-size: 11px;\r\n  color: var(--zn-text-muted);\r\n}\r\n.zhino-monitor-section {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 6px;\r\n}\r\n.zhino-monitor-label {\r\n  font-size: 12px;\r\n  color: var(--zn-text-regular);\r\n  font-weight: 500;\r\n}\r\n.zhino-monitor-pre {\r\n  background: var(--zn-bg-surface1);\r\n  border: 1px solid var(--zn-border-light);\r\n  border-radius: 6px;\r\n  padding: 10px;\r\n  font-size: 11px;\r\n  line-height: 1.5;\r\n  color: var(--zn-text-regular);\r\n  white-space: pre-wrap;\r\n  word-break: break-word;\r\n  max-height: 300px;\r\n  overflow-y: auto;\r\n  margin: 0;\r\n  font-family: inherit;\r\n}\r\n/* 代码日志：竖向滚动列表 */\r\n.zhino-codelog-list {\r\n  max-height: 420px;\r\n  overflow-y: auto;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 1px;\r\n}\r\n\r\n.zhino-codelog-entry {\r\n  cursor: pointer;\r\n  transition: background 0.15s ease;\r\n  border-left: 3px solid transparent;\r\n  padding-left: 10px;\r\n}\r\n.zhino-codelog-entry:hover {\r\n  background: var(--zn-bg-surface1);\r\n}\r\n.zhino-codelog-entry--info  { border-left-color: rgba(52, 211, 153, 0.6); }\r\n.zhino-codelog-entry--warn  { border-left-color: rgba(251, 191, 36, 0.6); }\r\n.zhino-codelog-entry--error { border-left-color: rgba(248, 113, 113, 0.6); }\r\n\r\n.zhino-codelog-row {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: 10px;\r\n  padding: 7px 12px 7px 0;\r\n  font-size: 11px;\r\n  line-height: 1.5;\r\n}\r\n\r\n.zhino-codelog-time {\r\n  flex-shrink: 0;\r\n  color: var(--zn-text-muted);\r\n  font-size: 10px;\r\n  font-variant-numeric: tabular-nums;\r\n  min-width: 54px;\r\n}\r\n\r\n.zhino-codelog-module {\r\n  flex-shrink: 0;\r\n  font-weight: 500;\r\n  color: var(--zn-text-primary);\r\n  min-width: 42px;\r\n  max-width: 60px;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.zhino-codelog-msg {\r\n  flex: 1;\r\n  color: var(--zn-text-regular);\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  min-width: 0;\r\n  /* 展开后长日志要能选中复制（排查靠它） */\r\n  user-select: text;\r\n}\r\n\r\n/* ⚠️ 展开态：日志内容常常很长（API 错误、槽位样本等），\r\n   单行省略会让人看不到关键信息 —— 展开时改为换行显示全文。 */\r\n.zhino-codelog-entry.is-expanded .zhino-codelog-row {\r\n  align-items: flex-start;\r\n}\r\n\r\n.zhino-codelog-entry.is-expanded .zhino-codelog-msg {\r\n  white-space: pre-wrap;\r\n  word-break: break-word;\r\n  overflow: visible;\r\n  text-overflow: clip;\r\n}\r\n\r\n.zhino-codelog-chevron {\r\n  flex-shrink: 0;\r\n  color: var(--zn-text-muted);\r\n  font-size: 10px;\r\n  width: 14px;\r\n  text-align: center;\r\n}\r\n\r\n.zhino-codelog-detail {\r\n  padding: 0 12px 10px 0;\r\n}\r\n\r\n.zhino-codelog-pre {\r\n  background: var(--zn-bg-surface1);\r\n  border: 1px solid var(--zn-border-light);\r\n  border-radius: 6px;\r\n  padding: 10px;\r\n  font-size: 11px;\r\n  line-height: 1.5;\r\n  color: var(--zn-text-regular);\r\n  white-space: pre-wrap;\r\n  word-break: break-word;\r\n  max-height: 180px;\r\n  overflow-y: auto;\r\n  margin: 0;\r\n  font-family: inherit;\r\n}\r\n\r\n.zhino-codelog-count {\r\n  font-size: 11px;\r\n  color: var(--zn-text-muted);\r\n  margin-right: auto;\r\n}\r\n/* ─── 选择性删除面板 ─── */\r\n.zhino-delete-panel {\r\n  margin-top: 10px;\r\n  padding: 12px;\r\n  background: rgba(255, 80, 60, 0.04);\r\n  border: 1px solid rgba(255, 80, 60, 0.15);\r\n  border-radius: 8px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 8px;\r\n}\r\n\r\n.zhino-delete-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  margin-bottom: 2px;\r\n}\r\n\r\n.zhino-delete-title {\r\n  font-size: 12px;\r\n  font-weight: 600;\r\n  color: var(--zn-text-primary);\r\n}\r\n\r\n.zhino-delete-select-all {\r\n  font-size: 11px;\r\n  color: var(--zn-text-regular);\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 4px;\r\n  cursor: pointer;\r\n}\r\n\r\n.zhino-delete-select-all input {\r\n  accent-color: #f5a623;\r\n}\r\n\r\n.zhino-delete-row {\r\n  padding: 4px 0;\r\n}\r\n\r\n.zhino-delete-label {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  cursor: pointer;\r\n  font-size: 12px;\r\n}\r\n\r\n.zhino-delete-label input {\r\n  accent-color: #f5a623;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.zhino-delete-block-name {\r\n  color: var(--zn-text-primary);\r\n  font-weight: 600;\r\n  min-width: 48px;\r\n}\r\n\r\n.zhino-delete-block-desc {\r\n  color: var(--zn-text-muted);\r\n  font-size: 10.5px;\r\n}\r\n\r\n.zhino-delete-block-count {\r\n  color: var(--zn-text-muted);\r\n  font-size: 10.5px;\r\n  margin-left: auto;\r\n}\r\n\r\n.zhino-delete-confirm {\r\n  display: flex;\r\n  gap: 8px;\r\n  align-items: center;\r\n  margin-top: 8px;\r\n}\r\n\r\n.zhino-delete-confirm-text {\r\n  font-size: 11px;\r\n  color: rgba(255, 150, 120, 0.7);\r\n}\r\n\r\n.zhino-delete-msg {\r\n  font-size: 11px;\r\n  padding: 4px 8px;\r\n  border-radius: 4px;\r\n}\r\n\r\n.zhino-delete-msg.ok {\r\n  color: rgba(100, 220, 150, 0.8);\r\n  background: rgba(100, 220, 150, 0.06);\r\n}\r\n\r\n.zhino-delete-msg.fail {\r\n  color: rgba(255, 150, 120, 0.8);\r\n  background: rgba(255, 150, 120, 0.06);\r\n}\r\n\r\n/* API 库弹窗 */\r\n/* API 库管理：section/card 在 Modal body 内，遮罩+卡片+头部+关闭 由 Modal 提供 */\r\n.zhino-api-lib-section {\r\n  margin-bottom: 16px;\r\n}\r\n.zhino-api-lib-subtitle {\r\n  font-size: 12px;\r\n  font-weight: 600;\r\n  color: var(--zn-text-regular);\r\n  margin-bottom: 8px;\r\n  border-bottom: 1px solid var(--zn-border-light);\r\n  padding-bottom: 4px;\r\n}\r\n.zhino-api-lib-card {\r\n  background: var(--zn-bg-surface2);\r\n  border: 1px solid var(--zn-border-light);\r\n  border-radius: 8px;\r\n  padding: 8px 12px;\r\n  margin-bottom: 8px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n}\r\n.zhino-api-lib-card-info {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 2px;\r\n 